const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

let state = flow.get("pcsDcMeasState") || {
    kind: "PcsDcMeasState",
    version: 1,
    // PCS_DC_MEAS (0x66B96Dx)
    pcs_acPwrFactor: null,
    pcs_totalBusV: null,
    pcs_posBusV: null,
    pcs_negBusV: null,
    // PCS_DC_MEAS_2 (0x66B96Ex)
    pcs_batV: null,
    pcs_batI: null,
    pcs_dcPwrKw: null,
    pcs_totalDcI: null
};

// Helper function
function s16(buf, offset) {
    let val = (buf[offset] & 0xFF) | ((buf[offset + 1] & 0xFF) << 8);
    return val > 32767 ? val - 65536 : val;
}

var processed = false;

// ==================== PCS_DC_MEAS (0x66B96Dx) ====================
if ((canId & 0xFFFFFFF0) === 0x66B96D0) {
    processed = true;

    // Bit 0-15: AC Power Factor
    // 16 bit, Signed, Factor: 0.01, Offset: 0
    // Min: -327.68, Max: 327.67
    state.pcs_acPwrFactor = s16(data, 0) * 0.01;

    // Bit 16-31: Total Bus Voltage
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: V
    // Min: 0, Max: 6553.5
    state.pcs_totalBusV = s16(data, 2) * 0.1;

    // Bit 32-47: Positive Bus Voltage
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: V
    // Min: 0, Max: 6553.5
    state.pcs_posBusV = s16(data, 4) * 0.1;

    // Bit 48-63: Negative Bus Voltage
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: V
    // Min: 0, Max: 6553.5
    state.pcs_negBusV = s16(data, 6) * 0.1;
}

// ==================== PCS_DC_MEAS_2 (0x66B96Ex) ====================
if ((canId & 0xFFFFFFF0) === 0x66B96E0) {
    processed = true;

    // Bit 0-15: Battery Voltage
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: V
    // Min: 0, Max: 6553.5
    state.pcs_batV = s16(data, 0) * 0.1;

    // Bit 16-31: Battery Current
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: A
    // Min: -3276.8, Max: 3276.7
    state.pcs_batI = s16(data, 2) * 0.1;

    // Bit 32-47: DC Power
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: kW
    // Min: -3276.8, Max: 3276.7
    state.pcs_dcPwrKw = s16(data, 4) * 0.1;

    // Bit 48-63: Total DC Current
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: A
    // Min: -3276.8, Max: 3276.7
    state.pcs_totalDcI = s16(data, 6) * 0.1;
}

if (!processed) {
    return null;
}

state.timestampUtc = new Date().toISOString();
flow.set("pcsDcMeasState", state);
msg.payload = state;
return msg;

var state = flow.get("pcsDcMeasState");
if (state) {
    msg.payload = state;
    return msg;
}
msg.payload = { error: "No data yet" };
return msg;
